function mean(a){return a.length?a.reduce((s,v)=>s+v,0)/a.length:0}function sd(a){if(a.length<2)return 0;const m=mean(a);return Math.sqrt(mean(a.map(v=>(v-m)**2)))}function valueRange(a){return a.length?Math.max(...a)-Math.min(...a):0}
function rms2(points){if(!points.length)return 0;const bx=mean(points.map(p=>p.x)),by=mean(points.map(p=>p.y));return Math.sqrt(mean(points.map(p=>(p.x-bx)**2+(p.y-by)**2)))}
function angle(a,b,c){if(!a||!b||!c)return NaN;const u={x:a.x-b.x,y:a.y-b.y},v={x:c.x-b.x,y:c.y-b.y},n=Math.hypot(u.x,u.y)*Math.hypot(v.x,v.y);return n?Math.acos(Math.max(-1,Math.min(1,(u.x*v.x+u.y*v.y)/n)))*180/Math.PI:NaN}
