function trackROI(w,h){if(!els.video.videoWidth)return;roiCanvas.width=Math.max(1,Math.round(w));roiCanvas.height=Math.max(1,Math.round(h));roiCtx.drawImage(els.video,0,0,w,h);const frame=roiCtx.getImageData(0,0,roiCanvas.width,roiCanvas.height).data;if(!roiTemplate){roiTemplate=grayPatch(frame,roiCanvas.width,roi.x,roi.y);roi.score=1;return}let best={sad:Infinity,x:roi.x,y:roi.y};for(let dy=-8;dy<=8;dy+=2)for(let dx=-8;dx<=8;dx+=2){const patch=grayPatch(frame,roiCanvas.width,roi.x+dx,roi.y+dy);let sad=0;for(let i=0;i<patch.length;i++)sad+=Math.abs(patch[i]-roiTemplate[i]);if(sad<best.sad)best={sad,x:roi.x+dx,y:roi.y+dy}}roi.x=Math.max(18,Math.min(w-18,best.x));roi.y=Math.max(18,Math.min(h-18,best.y));roi.score=Math.max(0,Math.min(1,1-best.sad/(roiTemplate.length*55)));if(roi.score>.72){const fresh=grayPatch(frame,roiCanvas.width,roi.x,roi.y);for(let i=0;i<fresh.length;i++)roiTemplate[i]=Math.round(roiTemplate[i]*.96+fresh[i]*.04)}}
function updateMetrics(m){els.scoreValue.textContent=m.score;els.scoreRing.style.setProperty("--score",m.score);els.roiRmsY.textContent=roi?m.roiRmsY.toFixed(2):"未設定";els.roiRmsX.textContent=roi?m.roiRmsX.toFixed(2):"未設定";els.foreAftRms.textContent=`${m.foreAftRms.toFixed(2)} %`;els.elbowAngle.textContent=`${m.elbow.toFixed(1)}°`;els.wristRms.textContent=`${m.wristRms.toFixed(2)} %`;els.roiRms.textContent=roi?`${m.roiRms.toFixed(2)} %`:"未設定";els.trunkAngle.textContent=`${Math.abs(m.trunk).toFixed(1)}°`;els.scoreLabel.textContent=!roi?"等待設定 ROI":m.score>=85?"持槍部位相對穩定":m.score>=65?"持槍部位輕微晃動":"持槍部位晃動較大";els.scoreHint.textContent=!roi?"點選槍口或準星附近作為主要追蹤區域。":m.roiRmsY>m.roiRmsX?"手槍 ROI 上下晃動較明顯，可對照呼吸與肩帶控制。":"手槍 ROI 前後晃動較明顯，可對照站姿與軀幹前後控制。"}
function setHudDirection(box,arrow,value,delta,threshold,negativeArrow,positiveArrow,negativeLabel,positiveLabel,unit="%") {const active=Math.abs(delta)>=threshold;box.classList.toggle("active",active);arrow.textContent=active?(delta<0?negativeArrow:positiveArrow):"•";value.textContent=active?`${delta<0?negativeLabel:positiveLabel} ${Math.abs(delta*(unit==="°"?1:100)).toFixed(unit==="°"?2:2)}${unit}`:"相對穩定"}
function updateMotionHud(m,d){els.hudScore.textContent=roi&&m.q>=.55?m.score:"—";els.hudTracking.textContent=!roi?"等待 ROI":m.q<.55?"未偵測到可靠骨架":`ROI ${(roi.score*100).toFixed(0)}%・骨架 ${(m.q*100).toFixed(0)}%`;setHudDirection(els.pitchDirection,els.pitchArrow,els.pitchValue,d.dy,.00035,"↑","↓","向上","向下");setHudDirection(els.yawDirection,els.yawArrow,els.yawValue,d.dx,.00035,"←","→","遠離","靠近");setHudDirection(els.depthDirection,els.depthArrow,els.depthValue,d.depth,.00055,"⇠","⇢","向後","向前")}
function roiCmCoordinates(points){if(!sessionBaseline)return[];return roiPoints(points).map(p=>({x:(p.roiNX-sessionBaseline.roiX)*sessionBaseline.cmPerX,y:-(p.roiNY-sessionBaseline.roiY)*sessionBaseline.cmPerY}))}
