function reportFilename(){const stamp=(reportSummary?.createdAt||new Date()).toISOString().replace(/[:.]/g,"-");return`AimTrace-檢測報告-${stamp}.png`}function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function downloadReport(){try{els.reportStatus.className="report-status";els.reportStatus.textContent="正在產生檢測報告…";const blob=await createReportBlob();downloadBlob(blob,reportFilename());els.reportStatus.textContent="檢測報告已下載。"}catch(error){els.reportStatus.className="report-status error";els.reportStatus.textContent=error.message}}
async function shareReport(){try{els.reportStatus.className="report-status";els.reportStatus.textContent="正在準備 LINE 分享…";const blob=await createReportBlob(),file=new File([blob],reportFilename(),{type:"image/png"});if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){await navigator.share({title:"AimTrace 空氣手槍穩定性檢測報告",text:`這是本次 AimTrace ${reportSummary.duration.toFixed(1)} 秒 ROI 持槍穩定性檢測報告，請在分享選單選擇 LINE。`,files:[file]});els.reportStatus.textContent="已開啟分享選單。"}else{downloadBlob(blob,file.name);els.reportStatus.className="report-status error";els.reportStatus.textContent="此瀏覽器不支援直接分享；報告已下載，請在 LINE 中選取圖片傳送。"}}catch(error){if(error.name==="AbortError")els.reportStatus.textContent="已取消分享。";else{els.reportStatus.className="report-status error";els.reportStatus.textContent=`分享失敗：${error.message}`}}}

